unitsize (2 cm);

pair A, B, C, D, E, F, H, P, Q, R;

B = (0,0);
C = (3,0);
A = intersectionpoint(arc(B,sqrt(7),0,180),arc(C,2,0,180));
D = (A + reflect(B,C)*(A))/2;
E = (B + reflect(C,A)*(B))/2;
F = (C + reflect(A,B)*(C))/2;
H = extension(A, D, B, E);
P = A + (2,0);
Q = P + 9*(D - A)/9;
R = Q + 4*(E - B)/9;

draw(A--B--C--cycle);
draw(A--D);
draw(B--E);
draw(C--F);
draw(P--Q--R--cycle);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, S);
label("$E$", E, NE);
label("$F$", F, NW);
